def show_figure(fig):
    if not CONFIG["runtime"]["display_figures"]:
        plt.close(fig)
        return
    # Notebook/Colab: render below the cell.
    try:
        ip = get_ipython()
    except NameError:
        ip = None
    if ip is not None and display is not None:
        display(fig)
        plt.close(fig)
    else:
        # Normal Python / macOS Terminal: open the real GUI figure.
        plt.show(block=True)
        plt.close(fig)


def profile_label(mode):
    return CONFIG["profiles"][mode]

