# =============================================================================
# DATA GETTERS
# =============================================================================
def get_active_goodput(mode, _case):
    return SCALAR_DATA["goodput"][mode]["active"]

def get_gap_goodput(mode, _case):
    return SCALAR_DATA["goodput"][mode]["gap_inclusive"]

def phase_endpoint_getter(metric, phase):
    def getter(mode, endpoint):
        return SCALAR_DATA[metric][phase][endpoint][mode]
    return getter

def get_active_cost(mode, _case):
    return SCALAR_DATA["j_per_gbit"]["active"][mode]

def get_whole_cost(mode, _case):
    return SCALAR_DATA["j_per_gbit"]["combined"][mode]

def get_duration(mode, case):
    return SCALAR_DATA["duration"][case][mode]

def get_total_transfer_duration(mode, _case):
    return TRANSFER_DURATION_DATA[mode]

def actual_dvfs_getter(scope, endpoint):
    def getter(mode, category):
        return PHASE_DVFS_DATA[scope][endpoint][mode][category]
    return getter

def idle_interval_getter(scope):
    def getter(mode, endpoint):
        return DIAGNOSTIC_DATA["idle_intervals"][scope][endpoint][mode]
    return getter

def ack_hint_getter(_mode, endpoint):
    return DIAGNOSTIC_DATA["quic_hints"][endpoint]["ACK_PENDING"]

def cubic_hint_getter(_mode, case):
    endpoint, kind = case.split(" / ", 1)
    return DIAGNOSTIC_DATA["quic_hints"][endpoint][kind]

def file_hint_getter(_mode, case):
    endpoint, kind = case.split(" / ", 1)
    return DIAGNOSTIC_DATA["quic_hints"][endpoint][kind]

# =============================================================================
# OUTPUT
# =============================================================================
def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "-output_path",
        "--output_path",
        default=None,
        help="Directory for generated charts. Default: GreenQUIC_results beside this script.",
    )
    args, _unknown = parser.parse_known_args()
    return args


def resolve_output_root():
    args = parse_args()
    if args.output_path:
        return Path(args.output_path).expanduser().resolve()
    try:
        base = Path(__file__).resolve().parent
    except NameError:
        base = Path.cwd()
    return base / "GreenQUIC_results"


OUTPUT_ROOT = resolve_output_root()
try:
    SCRIPT_DIR = Path(__file__).resolve().parent
except NameError:
    SCRIPT_DIR = Path.cwd().resolve()
if OUTPUT_ROOT == SCRIPT_DIR or OUTPUT_ROOT == Path(OUTPUT_ROOT.anchor):
    raise ValueError("output_path must point to a dedicated output directory")
if OUTPUT_ROOT.exists():
    shutil.rmtree(OUTPUT_ROOT)
OUTDIRS = {}
for fmt in ("svg", "pdf"):
    OUTDIRS[fmt] = {}
    for variant in ("with_values", "without_values", "timeseries"):
        p = OUTPUT_ROOT / fmt / variant
        p.mkdir(parents=True, exist_ok=True)
        OUTDIRS[fmt][variant] = p


def save_figure(fig, name, variant):
    if CONFIG["runtime"]["save_svg"]:
        fig.savefig(OUTDIRS["svg"][variant] / f"{name}.svg", dpi=CONFIG["figure"]["svg_dpi"], bbox_inches="tight")
    if CONFIG["runtime"]["save_pdf"]:
        fig.savefig(OUTDIRS["pdf"][variant] / f"{name}.pdf", dpi=CONFIG["figure"]["pdf_dpi"], bbox_inches="tight")

# =============================================================================
# COMMON FOUR-SECTION BAR STYLE
# =============================================================================
def build_grouped_x(modes, case_labels, spec):
    """Compact grouped-x geometry that scales with the number of bars."""
    ncases = len(case_labels)

    if "case_spacing" in spec:
        case_spacing = float(spec["case_spacing"])
    else:
        # Keep neighboring bars readable without wasting horizontal space.
        case_spacing = 1.000 if ncases <= 2 else 1.080

    if "config_gap" in spec:
        config_gap = float(spec["config_gap"])
    else:
        # A one-bar section should not consume the same width as a six-bar one.
        if ncases == 1:
            config_gap = 1.550
        elif ncases == 2:
            config_gap = 1.720
        else:
            config_gap = 1.920

    positions, labels, centers, separators = [], [], {}, []
    cursor = 0.000
    for i, mode in enumerate(modes):
        local = [cursor + j * case_spacing for j in range(ncases)]
        positions.extend(local)
        labels.extend(case_labels)
        centers[mode] = float(np.mean(local))
        if i < len(modes) - 1:
            next_start = local[-1] + config_gap
            separators.append((local[-1] + next_start) / 2.000)
            cursor = next_start
    return np.asarray(positions), labels, centers, separators


def dynamic_figure_width(modes, case_labels, spec):
    """
    Resize only the width from the amount of plotted content.
    Long x labels add a small safety margin so tick text does not collide.
    """
    figcfg = CONFIG["figure"]
    n_modes = len(modes)
    n_cases = len(case_labels)

    width = (
        float(figcfg["width_base_inches"])
        + n_modes * float(figcfg["width_per_mode_inches"])
        + n_modes * max(0, n_cases - 1) * float(figcfg["width_per_extra_case_inches"])
    )

    # Only the longest visible tick matters for the extra label allowance.
    longest = max((len(str(x).replace("\n", " ")) for x in case_labels), default=0)
    if longest > 12:
        width += min(
            2.800,
            (longest - 12) * float(figcfg["long_tick_label_extra_per_char_inches"])
            * max(1.000, min(3.000, n_cases / 2.000)),
        )

    if spec.get("dense_labels"):
        width += 0.800

    return max(
        float(figcfg["min_width_inches"]),
        min(float(figcfg["max_width_inches"]), width),
    )


def create_axis(spec, case_labels):
    modes = tuple(spec.get("modes", CONFIG_KEYS))
    figcfg = CONFIG["figure"]

    positions, labels, centers, separators = build_grouped_x(modes, case_labels, spec)
    width = dynamic_figure_width(modes, case_labels, spec)

    fig = plt.figure(figsize=(width, figcfg["height_inches"]), facecolor="white")
    plot_width = 1.000 - figcfg["plot_left"] - figcfg["legend_reserved_width"] - 0.030
    ax = fig.add_axes([figcfg["plot_left"], figcfg["plot_bottom"], plot_width, figcfg["plot_height"]])

    for spine in ax.spines.values():
        spine.set_linewidth(CONFIG["border"]["linewidth"])
        spine.set_color(CONFIG["border"]["color"])

    if CONFIG["grid"]["enabled"]:
        ax.grid(
            axis="y",
            alpha=CONFIG["grid"]["alpha"],
            linewidth=CONFIG["grid"]["linewidth"],
            linestyle=CONFIG["grid"]["linestyle"],
        )
        ax.set_axisbelow(True)

    ax.set_xticks(positions)
    rotation = spec.get("tick_rotation_deg", CONFIG["x_axis"]["tick_rotation_deg"])
    visible_labels = list(spec.get("tick_labels", labels))
    if len(visible_labels) == len(case_labels):
        visible_labels = visible_labels * len(modes)
    if len(visible_labels) != len(positions):
        visible_labels = labels
    ax.set_xticklabels(
        visible_labels,
        fontsize=float(spec.get("x_tick_label_size", CONFIG["font"]["x_tick_label_size"])),
        rotation=rotation,
        ha="right" if float(rotation) != 0 else "center",
        rotation_mode="anchor" if float(rotation) != 0 else None,
    )
    ax.tick_params(axis="x", pad=CONFIG["x_axis"]["tick_pad_points"])
    ax.tick_params(axis="y", labelsize=CONFIG["font"]["y_tick_label_size"])
    ax.set_ylabel(spec["y_label"], fontsize=CONFIG["font"]["y_axis_label_size"])

    fig.text(
        0.500 - figcfg["legend_reserved_width"] / 2.000,
        figcfg["title_y"],
        spec["title"],
        ha="center",
        va="center",
        fontsize=CONFIG["font"]["title_size"],
    )

    axes_height_inches = figcfg["height_inches"] * figcfg["plot_height"]
    profile_distance_cm = float(spec.get("profile_label_distance_below_axes_cm", figcfg["profile_label_distance_below_axes_cm"]))
    profile_y = -((profile_distance_cm / 2.540) / axes_height_inches)
    for mode, center in centers.items():
        ax.text(
            center,
            profile_y,
            profile_label(mode),
            transform=ax.get_xaxis_transform(),
            ha="center",
            va="top",
            fontsize=CONFIG["font"]["config_caption_size"],
            clip_on=False,
        )

    if CONFIG["x_axis"]["show_config_separator"]:
        for separator in separators:
            ax.axvline(
                separator,
                color=CONFIG["x_axis"]["separator_color"],
                linewidth=CONFIG["x_axis"]["separator_linewidth"],
                linestyle=CONFIG["x_axis"]["separator_linestyle"],
            )

    # Small side padding around the first and last bar instead of huge empty regions.
    if len(positions):
        left = float(np.min(positions)) - 0.620
        right = float(np.max(positions)) + 0.620
        ax.set_xlim(left, right)

    return fig, ax, positions, modes

def format_value(v, decimals):
    if v is None or not np.isfinite(float(v)):
        return "N/A"
    v = float(v)
    if v == 0:
        return "0"
    if decimals == 0:
        return f"{v:,.0f}"
    if round(v, decimals) == 0:
        return f"{v:.6f}"
    return f"{v:.{decimals}f}"


def apply_y(ax, spec, tops):
    finite = [float(v) for v in tops if v is not None and np.isfinite(float(v))]
    ymin = float(spec.get("y_min", 0))
    if spec.get("y_max") is not None:
        ymax = float(spec["y_max"])
    else:
        vmax = max(finite + [1.000])
        ymax = vmax * float(spec.get("headroom_factor", CONFIG["y_axis"]["headroom_factor"]))
    if ymax <= ymin:
        ymax = ymin + 1
    ax.set_ylim(ymin, ymax)
    if spec.get("major_step"):
        ax.yaxis.set_major_locator(mticker.MultipleLocator(float(spec["major_step"])))
    else:
        ax.yaxis.set_major_locator(mticker.MaxNLocator(nbins=int(spec.get("tick_count", CONFIG["y_axis"]["default_tick_count"]))))
    dec = int(spec.get("tick_decimals", 0))
    ax.yaxis.set_major_formatter(mticker.FormatStrFormatter(f"%.{dec}f"))


def add_value_label(ax, x, mean, sd, spec, show_values):
    if not show_values or mean is None or not np.isfinite(float(mean)):
        return
    mean = float(mean)
    sdv = None if sd is None or not np.isfinite(float(sd)) else float(sd)
    anchor = mean + (sdv or 0.000)
    text = format_value(mean, int(spec.get("value_decimals", 2))) + str(spec.get("value_suffix", ""))
    if CONFIG["bar_value_labels"]["show_sd"] and sdv is not None and not (mean == 0 and sdv == 0):
        text += "\n± " + format_value(sdv, int(spec.get("value_decimals", 2))) + str(spec.get("value_suffix", ""))
    points = CONFIG["bar_value_labels"]["distance_above_error_bar_cm"] / 2.540 * 72
    ax.annotate(text, xy=(x, anchor), xytext=(0, points), textcoords="offset points", ha="center", va="bottom", rotation=CONFIG["bar_value_labels"]["rotation_deg"], fontsize=CONFIG["font"]["dense_bar_value_text_size"] if spec.get("dense_labels") else CONFIG["font"]["bar_value_text_size"], clip_on=False)


def legend_for_categories(fig, ax, categories, colors):
    handles = [Patch(facecolor=colors[c], edgecolor="black", linewidth=0.400, label=c) for c in categories]
    leg = fig.legend(handles=handles, loc="center left", bbox_to_anchor=(ax.get_position().x1 + 0.004, 0.500), fontsize=CONFIG["font"]["legend_text_size"], frameon=True)
    leg.get_frame().set_linewidth(CONFIG["legend"]["frame_linewidth"])


def legend_for_modes(fig, ax, modes):
    handles = [Patch(facecolor=CONFIG["mode_colors"][m], edgecolor="black", linewidth=0.400, label=profile_label(m)) for m in modes]
    leg = fig.legend(handles=handles, loc="center left", bbox_to_anchor=(ax.get_position().x1 + 0.004, 0.500), fontsize=CONFIG["font"]["legend_text_size"], frameon=True)
    leg.get_frame().set_linewidth(CONFIG["legend"]["frame_linewidth"])


def plot_section_bars(spec, show_values=True):
    cases = tuple(spec["local_cases"])
    fig, ax, positions, modes = create_axis(spec, cases)
    seq_modes = [m for m in modes for _ in cases]
    seq_cases = list(cases) * len(modes)
    vals, errs, tops = [], [], []
    for mode in modes:
        for case in cases:
            item = spec["data_getter"](mode, case)
            vals.append(item.get("mean")); errs.append(item.get("sd"))
            if item.get("mean") is not None:
                tops.append(float(item["mean"]) + (0 if item.get("sd") is None else float(item["sd"])))
    apply_y(ax, spec, tops)
    for x, mode, case, mean, sd in zip(positions, seq_modes, seq_cases, vals, errs):
        if mean is None:
            continue
        color = CONFIG["mode_colors"][mode] if spec.get("color_by") == "mode" else spec["colors"][case]
        yerr = None if sd is None else float(sd)
        ax.bar(x, float(mean), width=float(spec.get("bar_width", 0.580)), color=color, edgecolor="black", linewidth=0.450, yerr=yerr, capsize=float(spec.get("capsize", 4)), error_kw={"elinewidth":0.900,"capthick":0.900})
        add_value_label(ax, x, mean, sd, spec, show_values)
    if spec.get("legend_kind", "categories") == "modes":
        legend_for_modes(fig, ax, modes)
    elif spec.get("legend_kind", "categories") == "categories":
        legend_for_categories(fig, ax, cases, spec["colors"])
    return fig

