# C-STATE CHARTS
# =============================================================================
def idle_fraction_getter(mode, case):
    text = case.replace("\n", " ")
    scope = "Active" if text.startswith("Transfer") else "Gap"
    endpoint = "Client" if text.endswith("Client") else "Server"
    return DIAGNOSTIC_DATA["idle_active_fraction"][scope][endpoint][mode]["Idle"]


def plot_cpu_idle_fraction(show_values=True):
    """One clear bar = idle fraction. Active fraction is simply 100 - idle."""
    cases = ("Transfer\nServer", "Transfer\nClient", "Gap\nServer", "Gap\nClient")
    spec = {
        "title": "CPU idle fraction — Server and Client",
        "y_label": "Fraction of phase duration (%)",
        "local_cases": cases,
        "modes": CONFIG_KEYS,
        "data_getter": idle_fraction_getter,
        "colors": {c: "#4C78A8" for c in cases},
        "color_by": "mode",
        "legend_kind": "none",
        "value_decimals": 2,
        "value_suffix": "%",
        "tick_decimals": 0,
        "y_min": 0,
        # Extra headroom prevents vertical mean/SD labels from touching the top border.
        "y_max": 120,
        "major_step": 10,
        "tick_rotation_deg": 0,
    }
    return plot_section_bars(spec, show_values)


def _cstate_value_text(v):
    """Compact percentage formatting used inside the stacked C-state bars."""
    v = float(v)
    if v == 0:
        return "0%"
    if v < 0.001:
        return f"{v:.6f}%"
    if v < 0.100:
        return f"{v:.3f}%"
    return f"{v:.2f}%"


def plot_cstate_residency_fraction(show_values=True):
    """
    ONE axes only.

    Each mode is one outer section. Inside each section are four stacked bars:
      Active Client, Active Server, Gap Client, Gap Server.

    POLL/C1/C1E/C6 are percentages of the COMPLETE corresponding phase duration.
    We deliberately avoid four separate subplot windows.
    """
    states = ("POLL", "C1", "C1E", "C6")
    cases = ("Transfer\nServer", "Transfer\nClient", "Gap\nServer", "Gap\nClient")
    modes = CONFIG_KEYS

    spec = {
        "title": "C-state residency fraction — Server and Client",
        "y_label": "Fraction of phase duration (%)",
        "modes": modes,
        "local_cases": cases,
        "tick_rotation_deg": 0,
        "x_tick_label_size": 10.500,
        "case_spacing": 1.240,
        "config_gap": 2.050,
        "profile_label_distance_below_axes_cm": 1.900,
        "dense_labels": True,
    }

    fig, ax, positions, _ = create_axis(spec, cases)
    seq_modes = [m for m in modes for _ in cases]
    seq_cases = list(cases) * len(modes)

    bottoms = np.zeros(len(positions), dtype=float)

    for state in states:
        heights = []
        errors = []
        for mode, case in zip(seq_modes, seq_cases):
            text = case.replace("\n", " ")
            scope = "active" if text.startswith("Transfer") else "gap"
            endpoint = "Client" if text.endswith("Client") else "Server"
            d = CSTATE_FRACTION_DATA[scope][endpoint][state][mode]
            heights.append(float(d["mean"]))
            errors.append(float(d["sd"]) if d.get("sd") is not None else 0.000)

        bars = ax.bar(
            positions,
            heights,
            bottom=bottoms,
            width=0.580,
            color=CONFIG["cstate_colors"][state],
            edgecolor="black",
            linewidth=0.400,
            label=state,
            zorder=3,
        )

        if show_values:
            for x, base, h in zip(positions, bottoms, heights):
                # Put a number only where the physical segment has enough height.
                # This removes the overlap problem from the old C-state chart.
                # Tiny values remain exact in CSTATE_FRACTION_DATA and in the
                # without-values/with-values source, but are not forced into a
                # sub-pixel segment.
                if h >= 1.800:
                    # Only label segments that physically have enough room.
                    # This is the with-values version, but forcing text into a
                    # <1.2% segment makes the numbers overlap and unreadable.
                    ax.text(
                        x,
                        base + h / 2.000,
                        _cstate_value_text(h),
                        ha="center",
                        va="center",
                        fontsize=6.600,
                        rotation=90 if h < 5.000 else 0,
                        clip_on=True,
                        zorder=5,
                    )

        bottoms += np.asarray(heights, dtype=float)

    ax.set_ylim(0, 105)
    ax.yaxis.set_major_locator(mticker.MultipleLocator(10))
    ax.yaxis.set_major_formatter(mticker.FormatStrFormatter("%.0f"))

    handles = [
        Patch(
            facecolor=CONFIG["cstate_colors"][state],
            edgecolor="black",
            linewidth=0.400,
            label=state,
        )
        for state in states
    ]
    leg = fig.legend(
        handles=handles,
        loc="center left",
        bbox_to_anchor=(ax.get_position().x1 + 0.004, 0.500),
        fontsize=CONFIG["font"]["legend_text_size"],
        frameon=True,
    )
    leg.get_frame().set_linewidth(CONFIG["legend"]["frame_linewidth"])

    return fig


