# =============================================================================
# PHASE BACKGROUND / WATERMARKS FOR TIME SERIES
# =============================================================================
def phase_kind(label):
    if label == "Startup": return "startup"
    if label == "Pre-cool": return "pre"
    if label.startswith("D"): return "download"
    if label.startswith("Gap"): return "gap"
    if label == "Post-cool": return "post"
    return "tail"


def watermark_font_size(duration, label):
    base = 16 if label.startswith("D") else 14 if label.startswith("Gap") else 10
    minimum = 6
    if duration >= 4: scale = 1.000
    elif duration >= 2: scale = 0.900
    elif duration >= 1: scale = 0.780
    elif duration >= 0.500: scale = 0.640
    elif duration >= 0.250: scale = 0.520
    else: scale = 0.440
    return max(minimum, base * scale)


def spans_for(data, mode, endpoint):
    ep = data[mode].get(endpoint, {})
    return ep.get("spans", data[mode].get("spans", []))


def add_phase_background(ax, spans):
    if not CONFIG["phase_background"]["enabled"]:
        return
    cfg = CONFIG["phase_background"]
    for span in spans:
        s=float(span["start"]); e=float(span["end"]); label=span["label"]
        kind=phase_kind(label)
        ax.axvspan(s,e,facecolor=cfg["colors"][kind],alpha=cfg["alpha"],linewidth=0,zorder=0)
        ax.text((s+e)/2, cfg["watermark_y"], label, transform=ax.get_xaxis_transform(), ha="center", va="center", fontsize=watermark_font_size(max(0,e-s),label), color=cfg["watermark_color"], alpha=cfg["watermark_alpha"], zorder=1, clip_on=True)


def style_timeseries_axis(ax):
    for spine in ax.spines.values():
        spine.set_linewidth(CONFIG["border"]["linewidth"]); spine.set_color(CONFIG["border"]["color"])
    ax.grid(axis="y", alpha=CONFIG["grid"]["alpha"], linewidth=CONFIG["grid"]["linewidth"])
    ax.set_axisbelow(True)
    ax.tick_params(axis="both", labelsize=CONFIG["font"]["y_tick_label_size"])


def plot_timeseries_endpoint(data, endpoint, title, y_label, line_style="line"):
    modes=CONFIG_KEYS
    fig_h=CONFIG["timeseries"]["panel_height_inches"]*len(modes)+1.550
    fig,axes=plt.subplots(len(modes),1,figsize=(CONFIG["timeseries"]["figure_width_inches"],fig_h),sharex=True,sharey=True)
    all_y=[]; all_starts=[]; all_ends=[]
    for mode in modes:
        d=data[mode][endpoint]
        if d.get("x"):
            all_y.extend([float(v) for v in d["y"] if np.isfinite(float(v))])
        sp=spans_for(data,mode,endpoint)
        if sp: all_starts.append(float(sp[0]["start"])); all_ends.append(float(sp[-1]["end"]))
    ymin=min(all_y) if all_y else 0; ymax=max(all_y) if all_y else 1
    margin=(ymax-ymin)*0.100 if ymax>ymin else 1
    if y_label.startswith("Frequency"):
        ymin=max(0,ymin-margin);ymax=min(4.100,ymax+margin)
    else:
        ymin=max(0,ymin-margin);ymax=ymax+margin
    xmin=min(all_starts)-CONFIG["timeseries"]["left_padding_seconds"]
    xmax=max(all_ends)+CONFIG["timeseries"]["right_padding_seconds"]
    for i,(ax,mode) in enumerate(zip(axes,modes)):
        style_timeseries_axis(ax)
        spans=spans_for(data,mode,endpoint);add_phase_background(ax,spans)
        d=data[mode][endpoint]; x=np.asarray(d.get("x",[]),float); y=np.asarray(d.get("y",[]),float)
        if len(x):
            if line_style=="step":
                ax.plot(x,y,color=CONFIG["mode_colors"][mode],linewidth=CONFIG["timeseries"]["frequency_line_width"],drawstyle="steps-post",zorder=3)
            else:
                ax.plot(x,y,color=CONFIG["mode_colors"][mode],linewidth=CONFIG["timeseries"]["line_width"],zorder=3)
        ax.set_ylim(ymin,ymax);ax.set_xlim(xmin,xmax)
        ax.text(0.012,0.910,profile_label(mode),transform=ax.transAxes,ha="left",va="top",fontsize=CONFIG["font"]["config_caption_size"],bbox=dict(facecolor="white",edgecolor="none",alpha=0.720,pad=2.000),zorder=5)
        if i<len(modes)-1: ax.tick_params(axis="x",labelbottom=False)
    axes[-1].set_xlabel("Time from start of Download 1 (s)",fontsize=CONFIG["font"]["x_axis_label_size"])
    fig.text(0.018,0.500,y_label,ha="center",va="center",rotation=90,fontsize=CONFIG["font"]["y_axis_label_size"])
    fig.suptitle(title,fontsize=CONFIG["font"]["title_size"],y=0.985,fontweight=CONFIG["font"]["weight"])
    fig.subplots_adjust(left=0.065,right=0.985,bottom=0.075,top=0.945,hspace=0.100)
    return fig


def plot_power_mode_overlay(mode):
    fig,ax=plt.subplots(figsize=(CONFIG["timeseries"]["figure_width_inches"],6.800))
    style_timeseries_axis(ax)
    spans=POWER_TIMESERIES_DATA[mode].get("spans") or spans_for(POWER_TIMESERIES_DATA,mode,"Combined")
    add_phase_background(ax,spans)
    all_y=[]
    for ep in ("Server","Client","Combined"):
        d=POWER_TIMESERIES_DATA[mode][ep];x=np.asarray(d["x"],float);y=np.asarray(d["y"],float);all_y.extend(y.tolist())
        ax.plot(x,y,color=CONFIG["endpoint_colors"][ep],linewidth=CONFIG["timeseries"]["line_width"],label=ep,zorder=3)
    ymin=max(0,min(all_y)*0.950);ymax=max(all_y)*1.080;ax.set_ylim(ymin,ymax)
    if spans: ax.set_xlim(float(spans[0]["start"])-0.750,float(spans[-1]["end"])+1.250)
    ax.set_xlabel("Time from start of Download 1 (s)",fontsize=CONFIG["font"]["x_axis_label_size"])
    ax.set_ylabel("CPU PKG + DRAM power (W)",fontsize=CONFIG["font"]["y_axis_label_size"])
    ax.set_title(f"CPU PKG + DRAM power over time — {profile_label(mode)}",fontsize=CONFIG["font"]["title_size"],pad=16)
    ax.legend(loc="upper right",fontsize=CONFIG["font"]["legend_text_size"],frameon=True)
    fig.tight_layout()
    return fig

