def _render_scalar(name):
    spec = CHARTS[name]
    if CONFIG["runtime"]["print_chart_name"]:
        print(f"=== {name} ===")
    fig = plot_section_bars(spec, True)
    save_figure(fig, name, "with_values")
    show_figure(fig)
    if CONFIG["runtime"]["save_without_values"]:
        fig = plot_section_bars(spec, False)
        save_figure(fig, name, "without_values")
        plt.close(fig)


