def render_all():
    # Main scalar charts.
    _render_scalar("01_active_goodput")
    _render_scalar("02_total_transfer_duration")
    # _render_scalar("02_workload_duration")

    _render_scalar("03_active_power")
    _render_scalar("04_gap_power")
    _render_scalar("05_active_energy")
    _render_scalar("06_gap_energy")
    _render_scalar("07_active_energy_cost")

    # C-state charts.
    # _render_idle_fraction()
    _render_cstate_fraction()
    _render_scalar("10_active_cstate_idle_intervals")
    _render_scalar("11_gap_cstate_idle_intervals")

    # Frequency summaries and DVFS changes.
    _render_scalar("12_active_frequency")
    _render_scalar("13_gap_frequency")
    _render_scalar("14_active_server_actual_dvfs_changes")
    _render_scalar("15_active_client_actual_dvfs_changes")
    _render_scalar("16_gap_server_actual_dvfs_changes")
    _render_scalar("17_gap_client_actual_dvfs_changes")

    # QUIC hints.
    _render_scalar("20_quic_ack_pending_hints")
    _render_scalar("21_quic_cubic_hints")
    _render_scalar("22_quic_file_transfer_hints")

    # CPU PKG + DRAM power time series.
    for endpoint in ("Server", "Client", "Combined"):
        name = f"{23 if endpoint == 'Server' else 24 if endpoint == 'Client' else 25}_{endpoint.lower()}_cpu_pkg_dram_power_over_time"
        if CONFIG["runtime"]["print_chart_name"]:
            print(f"=== {name} ===")
        fig = plot_timeseries_endpoint(
            POWER_TIMESERIES_DATA,
            endpoint,
            f"CPU PKG + DRAM power over time — {endpoint}",
            "CPU PKG + DRAM power (W)",
        )
        save_timeseries(fig, name)
        show_figure(fig)

    # CPU-frequency time-series figures are intentionally disabled for now.
    # Server, Client, and Combined frequency time-series data remain embedded above
    # so they can be re-enabled later without changing the input data.

    # Disabled time-series forms:
    #   27_off/basic/plus/linux_server_client_combined_rapl_power_over_time
    #   combined CPU-frequency time series

    # Source paths are also written beside the figures for quick checking.
    src = OUTPUT_ROOT / "SOURCE_REFERENCE.txt"
    with src.open("w") as f:
        for key, value in CHART_SOURCE_REFERENCE.items():
            f.write(f"{key}: {value}\n")
        f.write(
            "23_server / 24_client / 25_combined CPU PKG + DRAM power over time: "
            "P5 the_sheet_rules_all(2).zip :: 58/60/62_*_endpoints_power_smoothed.svg; "
            "Linux P7_LINUX_PAPER_6r_6d_20260816_203454(1).zip :: runs/server|client/rep01..rep06/rapl.csv + summary.json\n"
        )

    print(f"DONE: {OUTPUT_ROOT}")


render_all()
